      switch (dangerValue) {
        case '低': $dangerSeal.addClass('danger-low'); sealText = '安'; break;
        case '中低': $dangerSeal.addClass('danger-medium-low'); sealText = '警'; break;
        case '中': $dangerSeal.addClass('danger-medium'); sealText = '戒'; break;
        case '高': $dangerSeal.addClass('danger-high'); sealText = '危'; break;
        case '极高': $dangerSeal.addClass('danger-extreme'); sealText = '死'; break;
        default: $dangerSeal.css('background-color', '#888'); break;
      }
      $dangerSeal.text(sealText);
      $dangerContainer.append($('<span>').addClass('property-value').text(dangerValue));
      $dangerContainer.append($dangerSeal);

      /* Populate Team & Items */
      setList('stat-members', data.成员);
      setList('stat-items', data.物品);
    }

    /* Toggles the visibility of a section */
    function toggleSection($header) {
      const $content = $header.next('.section-content');
      $content.toggleClass('expanded');
      const $arrow = $header.find('span:last-child');
      $arrow.text($content.hasClass('expanded') ? '收' : '展');
